python3 -c "
import yaml
with open('registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})
done_outcomes = {}
for k, v in exps.items():
    if v.get('status') == 'DONE':
        o = v.get('outcome', 'unknown')
        done_outcomes[o] = done_outcomes.get(o, 0) + 1
for o, c in sorted(done_outcomes.items()):
    print(f'  {o}: {c}')
"
